def min_coins(coins, amount):
 INF = float("inf")
 dp = [0] + [INF] * amount # dp[x] = fewest coins to make x
 for x in range(1, amount + 1):
 for c in coins:
 if c <= x and dp[x - c] + 1 < dp[x]:
 dp[x] = dp[x - c] + 1
 return dp[amount] if dp[amount] != INF else -1
Greedy (always take the biggest coin) fails here: with coins {1, 3, 4} and amount 6, greedy gives 4+1+1 (three coins), DP finds 3+3 (two). Cost O(amount × coins).

from collections import deque
def bfs(g, start): # g = {node: [neighbors]}
 dist = {start: 0}
 q = deque([start])
 while q:
 u = q.popleft()
 for v in g[u]:
 if v not in dist:
 dist[v] = dist[u] + 1
 q.append(v)
 return dist # fewest hops to every reachable node
def dfs(g, u, seen=None):
 seen = seen if seen is not None else set()
 seen.add(u)
 for v in g[u]:
 if v not in seen: dfs(g, v, seen)
 return seen
Mark nodes seen when you enqueue/push them, not later, or you will visit the same node many times.

import heapq
def dijkstra(g, src): # g = {u: [(v, w), ...]}
 dist = {src: 0}
 pq = [(0, src)]
 while pq:
 d, u = heapq.heappop(pq)
 if d > dist.get(u, float("inf")): continue # stale entry
 for v, w in g[u]:
 nd = d + w
 if nd < dist.get(v, float("inf")):
 dist[v] = nd
 heapq.heappush(pq, (nd, v))
 return dist
Greedy idea: the closest unfinished node already has its final distance because all weights are non-negative. Cost O((V + E) log V) with a heap. Bellman-Ford (relax every edge V−1 times, O(VE)) handles negative weights and detects negative cycles. A\* adds a heuristic estimate of remaining distance to guide the search (maps, games).

class ChainTable:
 def __init__(self, n=8):
 self.b = [[] for _ in range(n)]
 self.size = 0
 def _slot(self, k): return self.b[hash(k) % len(self.b)]
 def put(self, k, v):
 s = self._slot(k)
 for i, (kk, _) in enumerate(s):
 if kk == k: s[i] = (k, v); return
 s.append((k, v)); self.size += 1
 if self.size > 0.75 * len(self.b): self._grow()
 def get(self, k):
 for kk, v in self._slot(k):
 if kk == k: return v
 raise KeyError(k)
 def _grow(self):
 old = [kv for s in self.b for kv in s]
 self.b = [[] for _ in range(2 * len(self.b))]
 self.size = 0
 for k, v in old: self.put(k, v)

